function StatisticsPage({ data }) {
  const speciesData = useMemo(() => {
    const m = {};
    data.forEach(d => {
      const s = getShortSpecies(d["Species name"]);
      m[s] = (m[s] || 0) + 1;
    });
    return Object.entries(m).map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count);
  }, [data]);

  const ptmData = useMemo(() => {
    const m = {};
    data.forEach(d => {
      const p = d["PTM"];
      if (p !== "-") { m[p] = (m[p] || 0) + 1; }
      else m["None"] = (m["None"] || 0) + 1;
    });
    return Object.entries(m).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value);
  }, [data]);

  const locData = useMemo(() => {
    const m = {};
    data.forEach(d => {
      const l = d["Subcellular location"] === "-" ? "Unknown" : d["Subcellular location"].split(",")[0].trim();
      m[l] = (m[l] || 0) + 1;
    });
    return Object.entries(m).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value);
  }, [data]);

  const sizeData = useMemo(() => data.filter(d => d["No of amino acids"] > 0).map(d => ({ x: d["No of amino acids"], y: typeof d["Mol. wt"] === "number" ? d["Mol. wt"] : 0, name: d["Protein name"] })), [data]);

  const CHART_COLORS = SPECIES_COLORS;
  const TOOLTIP_STYLE = { background: "#ffffff", border: "1.5px solid rgba(4,108,72,0.25)", borderRadius: 8, fontFamily: "monospace", fontSize: "0.82rem", color: "#011a0d", boxShadow: "0 4px 16px rgba(4,108,72,0.12)", padding: "8px 12px" };

  return (
    <div>
      <div className="sec-head"><h2 className="sec-title">Database <em>Statistics</em></h2></div>
      <div className="grid grid-2" style={{ marginBottom: "1.5rem" }}>
        <div className="chart-card">
          <div className="chart-title">Proteins per Species</div>
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={speciesData} margin={{ left: -10 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(4,108,72,0.15)" />
              <XAxis dataKey="name" tick={{ fontSize: 10, fill: "#2d6448" }} angle={-30} textAnchor="end" height={60} />
              <YAxis tick={{ fontSize: 10, fill: "#2d6448" }} />
              <Tooltip contentStyle={TOOLTIP_STYLE} />
              <Bar dataKey="count" fill="#0d9488" radius={[3, 3, 0, 0]}>
                {speciesData.map((_, i) => <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />)}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
        <div className="chart-card">
          <div className="chart-title">PTM Distribution</div>
          <ResponsiveContainer width="100%" height={280}>
            <PieChart>
              <Pie data={ptmData} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={100} label={({ name, percent }) => `${name.split(",")[0]} ${(percent * 100).toFixed(0)}%`} labelLine={false} fontSize={9}>
                {ptmData.map((_, i) => <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />)}
              </Pie>
              <Tooltip contentStyle={TOOLTIP_STYLE} />
            </PieChart>
          </ResponsiveContainer>
        </div>
        <div className="chart-card">
          <div className="chart-title">Subcellular Localization</div>
          <ResponsiveContainer width="100%" height={260}>
            <BarChart data={locData} layout="vertical" margin={{ left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(4,108,72,0.15)" horizontal={false} />
              <XAxis type="number" tick={{ fontSize: 10, fill: "#2d6448" }} />
              <YAxis dataKey="name" type="category" tick={{ fontSize: 10, fill: "#2d6448" }} width={90} />
              <Tooltip contentStyle={TOOLTIP_STYLE} />
              <Bar dataKey="value" fill="#60a5fa" radius={[0, 3, 3, 0]}>
                {locData.map((_, i) => <Cell key={i} fill={CHART_COLORS[(i + 5) % CHART_COLORS.length]} />)}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
        <div className="chart-card">
          <div className="chart-title">Amino Acid Length vs Molecular Weight</div>
          <ResponsiveContainer width="100%" height={260}>
            <ScatterChart margin={{ left: -10 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(4,108,72,0.15)" />
              <XAxis dataKey="x" name="AA Length" tick={{ fontSize: 10, fill: "#2d6448" }} label={{ value: "Amino Acids", position: "insideBottom", offset: -5, fill: "#5eada5", fontSize: 10 }} />
              <YAxis dataKey="y" name="Mol. Wt" tick={{ fontSize: 10, fill: "#2d6448" }} />
              <Tooltip contentStyle={TOOLTIP_STYLE} cursor={{ strokeDasharray: "3 3" }} formatter={(v, n) => [v.toLocaleString(), n]} />
              <Scatter data={sizeData} fill="#0d9488" opacity={0.7} />
            </ScatterChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(160px, 1fr))", gap: "1rem" }}>
        {[
          { label: "Total Proteins", val: data.length, icon: "🧬" },
          { label: "Species", val: new Set(data.map(d => d["Species name"])).size, icon: "🌿" },
          { label: "With Structure", val: data.filter(d => d["Structure (Yes/No)"] === "Yes").length, icon: "🔬" },
          { label: "Secreted", val: data.filter(d => d["Subcellular location"] === "Secreted").length, icon: "💧" },
          { label: "With PTM", val: data.filter(d => d["PTM"] !== "-").length, icon: "🔗" },
          { label: "With Gene", val: data.filter(d => d["Gene name"] !== "-").length, icon: "🧫" },
        ].map(s => (
          <div key={s.label} style={{ background: "var(--surface)", border: "1px solid var(--border)", borderRadius: "var(--radius-lg)", padding: "1.25rem", textAlign: "center" }}>
            <div style={{ fontSize: "1.5rem", marginBottom: "0.5rem" }}>{s.icon}</div>
            <div style={{ fontFamily: "var(--font-mono)", fontSize: "1.8rem", color: "var(--accent)", fontWeight: 700 }}>{s.val}</div>
            <div style={{ fontSize: "0.73rem", color: "var(--text-muted)", marginTop: "2px" }}>{s.label}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

