function OtherLinksPage() {
  const tools = [
    { icon: "🔵", name: "UniProt", desc: "Universal protein sequence and functional information database with manually curated Swiss-Prot entries.", url: "https://www.uniprot.org", cat: "Database" },
    { icon: "🧬", name: "NCBI Protein", desc: "National Center for Biotechnology Information protein sequence database including GenBank, RefSeq.", url: "https://www.ncbi.nlm.nih.gov/protein", cat: "Database" },
    { icon: "🔮", name: "PDB", desc: "Worldwide Protein Data Bank — 3D structural data for biological macromolecules.", url: "https://www.rcsb.org", cat: "Structure" },
    { icon: "🌀", name: "InterPro", desc: "Protein family and domain classification database integrating multiple member databases.", url: "https://www.ebi.ac.uk/interpro", cat: "Analysis" },
    { icon: "🔍", name: "BLAST", desc: "Basic Local Alignment Search Tool for comparing protein/nucleotide sequences against databases.", url: "https://blast.ncbi.nlm.nih.gov", cat: "Tool" },
    { icon: "📐", name: "ClustalOmega", desc: "Multiple sequence alignment tool for protein and DNA sequences.", url: "https://www.ebi.ac.uk/Tools/msa/clustalo", cat: "Tool" },
    { icon: "🧪", name: "AlphaFold DB", desc: "AI-predicted 3D protein structures for nearly all known proteins.", url: "https://alphafold.ebi.ac.uk", cat: "Structure" },
    { icon: "📊", name: "ExPASy", desc: "Bioinformatics resource portal for proteomics tools and databases.", url: "https://www.expasy.org", cat: "Portal" },
    { icon: "🌿", name: "NCBI Taxonomy", desc: "Comprehensive database of organismal names and classifications.", url: "https://www.ncbi.nlm.nih.gov/taxonomy", cat: "Database" },
    { icon: "🔬", name: "STRING", desc: "Known and predicted protein-protein interaction networks.", url: "https://string-db.org", cat: "Analysis" },
    { icon: "📚", name: "PubMed", desc: "Free access to MEDLINE biomedical and life science literature.", url: "https://pubmed.ncbi.nlm.nih.gov", cat: "Literature" },
    { icon: "🧫", name: "Pfam", desc: "Database of protein families and domains based on hidden Markov models.", url: "https://pfam.xfam.org", cat: "Analysis" },
  ];
  const cats = ["All", ...Array.from(new Set(tools.map(t => t.cat)))];
  const [activeCat, setActiveCat] = useState("All");
  const filtered = activeCat === "All" ? tools : tools.filter(t => t.cat === activeCat);
  return (
    <div>
      <div className="sec-head"><h2 className="sec-title">External <em>Resources</em></h2></div>
      <div className="az-bar" style={{ marginBottom: "1.25rem" }}>
        {cats.map(c => <button key={c} className={`az-btn all ${activeCat === c ? "active" : ""}`} onClick={() => setActiveCat(c)}>{c}</button>)}
      </div>
      <div className="tools-grid">
        {filtered.map(t => (
          <div className="tool-card" key={t.name}>
            <div className="tool-icon">{t.icon}</div>
            <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", marginBottom: "0.35rem" }}>
              <div className="tool-name">{t.name}</div>
              <Badge text={t.cat} type="dim" />
            </div>
            <div className="tool-desc">{t.desc}</div>
            <a className="tool-link" href={t.url} target="_blank" rel="noreferrer">{t.url} ↗</a>
          </div>
        ))}
      </div>
    </div>
  );
}

// ─── APP ROOT ─────────────────────────────────────────────────────────────────
const TABS = [
  { id: "home", label: "Home" },
  { id: "intro", label: "Introduction" },
  { id: "database", label: "Database" },
  { id: "function", label: "Function" },
  { id: "species", label: "Species" },
  { id: "gallery", label: "Gallery" },
  { id: "genome", label: "Genome" },
  { id: "statistics", label: "Statistics" },
  { id: "references", label: "References" },
  { id: "contact", label: "Contact" },
  { id: "links", label: "Other Links" },
];

export default function App() {
  const [activeTab, setActiveTab] = useState("home");
  const [dbSearch, setDbSearch] = useState("");

  const navigate = (tab, search = "") => {
    setActiveTab(tab);
    if (tab === "database" && search) setDbSearch(search);
  };

  const selectProtein = name => {
    setActiveTab("database");
    setDbSearch(name);
  };

  return (
    <>
      <style>{CSS}</style>
      <div className="app">
        <header className="header">
          <div className="header-inner">
            {/* LEFT: leech logo + site name */}
            <div className="logo">
              <div className="logo-icon" style={{fontSize:"1.8rem",lineHeight:1}}>🪱</div>
              <div>
                <div className="logo-text">Leech<span>DB</span></div>
                <div className="logo-sub">(LBD) Leech Bioinformatics Database</div>
              </div>
            </div>

            {/* CENTER: navigation */}
            <nav className="nav">
              {TABS.map(t => (
                <button key={t.id} className={"nav-btn" + (activeTab === t.id ? " active" : "")} onClick={() => navigate(t.id)}>{t.label}</button>
              ))}
            </nav>

            {/* RIGHT: college logo + badge */}
            <div className="header-right">
              <div className="header-badge">80 Proteins · 14 Species</div>
              <div className="college-badge" title="Saveetha Institute of Medical and Technical Sciences (SIMATS Engineering)">
                <img src={LOGO_URI} alt="SIMATS Engineering" />
                <span>SIMATS<br/>Engineering</span>
              </div>
            </div>
          </div>
        </header>
        <main className="main">
          {activeTab === "home"       && <HomePage data={RAW_DATA} onNavigate={navigate} />}
          {activeTab === "intro"      && <IntroPage />}
          {activeTab === "database"   && <DatabasePage data={RAW_DATA} initialSearch={dbSearch} />}
          {activeTab === "function"   && <FunctionPage data={RAW_DATA} onSelect={selectProtein} />}
          {activeTab === "species"    && <SpeciesPage data={RAW_DATA} onSelect={selectProtein} />}
          {activeTab === "gallery"    && <GalleryPage />}
          {activeTab === "genome"     && <GenomePage />}
          {activeTab === "statistics" && <StatisticsPage data={RAW_DATA} />}
          {activeTab === "references" && <ReferencesPage />}
          {activeTab === "contact"    && <ContactPage />}
          {activeTab === "links"      && <OtherLinksPage />}
        </main>
      </div>
    </>
  );
}
